local BagpipeMaker = {}
local PRODUCTS = {
    village_bagpipe = { name = "Vasja dude", woodCost = 1, leatherCost = 2, reedCost = 1, time = 3, cost = 50, soundQuality = 10, prestige = 1, description = "Preproste dude za vasi." },
    court_bagpipe = { name = "Dvorne dude", woodCost = 2, leatherCost = 2, reedCost = 2, time = 5, cost = 140, soundQuality = 14, prestige = 3, description = "Dvorne dude z dve rožičevima." },
    silver_chanter_bagpipe = { name = "Srebrnjačeve dude", woodCost = 2, silverCost = 1, leatherCost = 2, reedCost = 2, time = 7, cost = 340, soundQuality = 18, prestige = 7, happiness = 1, description = "Dude s srebrnim rožičem za plemiče." },
    italian_bagpipe = { name = "Italijanske dude", woodCost = 3, silverCost = 1, leatherCost = 3, reedCost = 2, time = 9, cost = 700, soundQuality = 22, prestige = 12, happiness = 2, description = "Italijanske dude z bogatim zvokom." },
    gold_trim_bagpipe = { name = "Zlatorobne dude", woodCost = 3, goldCost = 1, silverCost = 1, leatherCost = 3, reedCost = 2, time = 12, cost = 1400, soundQuality = 27, prestige = 20, happiness = 4, description = "Dude z zlatorobnim okovjem." },
    royal_ceremonial_bagpipe = { name = "Kraljevske slovesne dude", woodCost = 4, goldCost = 2, silverCost = 1, ivoryCost = 1, leatherCost = 3, reedCost = 3, pearlCost = 1, time = 16, cost = 2500, soundQuality = 38, prestige = 50, happiness = 10, description = "Velike kraljevske slovesne dude z zlatim, slonokoščenim in bisernim okovjem." },
}
local BUILDINGS = {
    workshop = { name = "Dudarska delavnica", cost = { gold = 260, wood = 130 }, upkeep = 6, qualityBonus = 5 },
    leather_room = { name = "Usnjiška soba", cost = { gold = 800, wood = 220, stone = 200, leather = 8 }, upkeep = 20, qualityBonus = 18 },
    reed_room = { name = "Trobilnica", cost = { gold = 1700, wood = 280, stone = 350, silver = 25, reed = 8 }, upkeep = 40, qualityBonus = 30 },
    royal_bagpipe_atelier = { name = "Kraljevski atelje dud", cost = { gold = 6500, wood = 500, stone = 700, gold = 50, ivory = 20 }, upkeep = 120, qualityBonus = 55, prestigeBonus = 30 },
}
BagpipeMaker.woodStock = 14; BagpipeMaker.leatherStock = 12; BagpipeMaker.reedStock = 12; BagpipeMaker.silverStock = 6; BagpipeMaker.goldStock = 6; BagpipeMaker.ivoryStock = 6; BagpipeMaker.pearlStock = 4
BagpipeMaker.productStock = {}; BagpipeMaker.buildings = {}; BagpipeMaker.maker = nil; BagpipeMaker.activeMaking = {}; BagpipeMaker.totalProducts = 0; BagpipeMaker.dayTimer = 0
function BagpipeMaker.init() BagpipeMaker.woodStock=14; BagpipeMaker.leatherStock=12; BagpipeMaker.reedStock=12; BagpipeMaker.silverStock=6; BagpipeMaker.goldStock=6; BagpipeMaker.ivoryStock=6; BagpipeMaker.pearlStock=4; BagpipeMaker.productStock={}; BagpipeMaker.buildings={}; BagpipeMaker.maker=nil; BagpipeMaker.activeMaking={}; BagpipeMaker.totalProducts=0; BagpipeMaker.dayTimer=0; print("[BagpipeMaker] Royal Bagpipe Maker System initialized (6 products, 4 buildings)") end
function BagpipeMaker.hireMaker(n,s) s=s or math.random(50,90); local c=470+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BagpipeMaker.maker={name=n or ("Dudar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Dudar najet: %s (spretnost: %d)",BagpipeMaker.maker.name,s),"success") end; return true end
function BagpipeMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BagpipeMaker.build(id) local ok,e=BagpipeMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BagpipeMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BagpipeMaker.getQualityBonus() local b=0; for _,bd in ipairs(BagpipeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BagpipeMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and BagpipeMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BagpipeMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.reedCost and BagpipeMaker.reedStock<(d.reedCost or 0) then return false,"Premalo trobil" end; if d.silverCost and BagpipeMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BagpipeMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.ivoryCost and BagpipeMaker.ivoryStock<(d.ivoryCost or 0) then return false,"Premalo slonovine" end; if d.pearlCost and BagpipeMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BagpipeMaker.buildings==0 then return false,"Potrebna delavnica" end; if not BagpipeMaker.maker then return false,"Potreben dudar" end; return true end
function BagpipeMaker.make(pt,qty) qty=qty or 1; local ok,e=BagpipeMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then BagpipeMaker.woodStock=BagpipeMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BagpipeMaker.leatherStock=BagpipeMaker.leatherStock-d.leatherCost*qty end; if d.reedCost then BagpipeMaker.reedStock=BagpipeMaker.reedStock-d.reedCost*qty end; if d.silverCost then BagpipeMaker.silverStock=BagpipeMaker.silverStock-d.silverCost*qty end; if d.goldCost then BagpipeMaker.goldStock=BagpipeMaker.goldStock-d.goldCost*qty end; if d.ivoryCost then BagpipeMaker.ivoryStock=BagpipeMaker.ivoryStock-d.ivoryCost*qty end; if d.pearlCost then BagpipeMaker.pearlStock=BagpipeMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BagpipeMaker.maker then t=math.max(1,t-math.floor(BagpipeMaker.maker.skill/12)) end; table.insert(BagpipeMaker.activeMaking,{id="bagpipe_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,soundQuality=d.soundQuality or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BagpipeMaker.completeMaking(m) local q=1.0+(BagpipeMaker.getQualityBonus()/100); if BagpipeMaker.maker then q=q+(BagpipeMaker.maker.skill/180) end; q=math.min(2.0,q); BagpipeMaker.productStock[m.productType]=(BagpipeMaker.productStock[m.productType] or 0)+m.quantity; BagpipeMaker.totalProducts=BagpipeMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BagpipeMaker.maker then BagpipeMaker.maker.itemsMade=BagpipeMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then BagpipeMaker.maker.skill=math.min(100,BagpipeMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Dude izdelane: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bagpipe.completed",{productName=m.productName,soundQuality=m.soundQuality}) end end
function BagpipeMaker.update(dt) if not _G.state then return end; BagpipeMaker.dayTimer=BagpipeMaker.dayTimer+dt; if BagpipeMaker.dayTimer>=30 then BagpipeMaker.dayTimer=0; for i=#BagpipeMaker.activeMaking,1,-1 do local m=BagpipeMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BagpipeMaker.completeMaking(m); table.remove(BagpipeMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BagpipeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BagpipeMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BagpipeMaker.getStats() return {woodStock=BagpipeMaker.woodStock,leatherStock=BagpipeMaker.leatherStock,reedStock=BagpipeMaker.reedStock,silverStock=BagpipeMaker.silverStock,goldStock=BagpipeMaker.goldStock,ivoryStock=BagpipeMaker.ivoryStock,pearlStock=BagpipeMaker.pearlStock,productStock=BagpipeMaker.productStock,numBuildings=#BagpipeMaker.buildings,hasMaker=BagpipeMaker.maker~=nil,makerName=BagpipeMaker.maker and BagpipeMaker.maker.name or "—",makerSkill=BagpipeMaker.maker and BagpipeMaker.maker.skill or 0,activeMaking=#BagpipeMaker.activeMaking,totalProducts=BagpipeMaker.totalProducts} end
return BagpipeMaker
